 ['a URL split into its parts, query strings read and written', "import urllib.parse as up\nurl = 'https://api.openweathermap.org/geo/1.0/direct?q=San Francisco,CA,US&appid=KEY'\np = up.urlsplit(url)\nprint(p.scheme, p.netloc, p.path, p.query, sep=' | ')\nprint(up.parse_qs(p.query))\nprint(up.urlencode({'q': 'San Francisco,CA,US', 'appid': 'KEY'}))\nprint(up.urlunsplit(('https', 'api.openweathermap.org', '/geo/1.0/direct', up.urlencode({'q': 'San Francisco,CA,US', 'appid': 'KEY'}), '')))\nprint(up.urljoin('https://pypi.org/search/?q=x', '/project/pyautogui'))\nprint(up.urlsplit('https://www.openstreetmap.org/search?query=777#map=19/37.75897/-122.42142').fragment)\n", "https | api.openweathermap.org | /geo/1.0/direct | q=San Francisco,CA,US&appid=KEY\n{'q': ['San Francisco,CA,US'], 'appid': ['KEY']}\nq=San+Francisco%2CCA%2CUS&appid=KEY\nhttps://api.openweathermap.org/geo/1.0/direct?q=San+Francisco%2CCA%2CUS&appid=KEY\nhttps://pypi.org/project/pyautogui\nmap=19/37.75897/-122.42142"],
